const thresholdPct=Number($input.first().json['跌幅門檻（%）']);
if(!Number.isFinite(thresholdPct)||thresholdPct<=0||thresholdPct>=100)throw new Error('跌幅門檻必須介於0與100之間。');
const manual=$('手動測試').isExecuted;
const now=$now.setZone('America/New_York');
if(!manual&&(now.weekday>5||now.hour<17))return [];
return [{json:{manual,thresholdPct,symbols:$input.first().json['股票代號'],marketDate:now.toISODate(),checkedAt:now.toISO(),recipient:String($input.first().json['LINE收件人UserID']||'').trim()}}];

const ctx=$('股票與通知設定').first().json;
const raw=$input.first().json;
if(raw.status==='error')throw new Error('行情API失敗，請檢查憑證、額度或執行紀錄。');
const results=[];
for(const symbol of ctx.symbols){
 const r=raw[symbol];
 if(!r||r.status==='error'||!Array.isArray(r.values)||r.values.length<2)throw new Error(symbol+'：缺少兩個交易日資料，不計算跌幅。');
 if(r.meta?.symbol!==symbol||r.meta?.currency!=='USD'||r.meta?.exchange_timezone!=='America/New_York')throw new Error(symbol+'：行情市場或幣別不符。');
 const rows=[...r.values].sort((a,b)=>String(b.datetime).localeCompare(String(a.datetime)));
 const [latest,previous]=rows;
 if(!/^\d{4}-\d{2}-\d{2}$/.test(latest.datetime)||!/^\d{4}-\d{2}-\d{2}$/.test(previous.datetime)||latest.datetime<=previous.datetime)throw new Error(symbol+'：交易日期異常。');
 if(!ctx.manual&&latest.datetime!==ctx.marketDate)continue;
 const a=Number(latest.close),b=Number(previous.close);
 if(!Number.isFinite(a)||!Number.isFinite(b)||a<=0||b<=0)throw new Error(symbol+'：收盤價無效。');
 const changePct=(a-b)/b*100;
 results.push({symbol,date:latest.datetime,previousDate:previous.datetime,close:a,previousClose:b,changePct,thresholdPct:ctx.thresholdPct,isDrop:changePct < -ctx.thresholdPct-1e-10});
}
return results.map(r=>({json:{...r,checkedAt:ctx.checkedAt,recipient:ctx.recipient}}));

const store=$getWorkflowStaticData('global');const sent=store.sent||{};
const manual=$('股票與通知設定').first().json.manual;
const alerts=$input.all().map(i=>i.json).filter(r=>manual||!sent[r.symbol+':'+r.date]);
if(!alerts.length)return [];
if(new Set(alerts.map(r=>r.date)).size!==1)throw new Error('通知股票交易日期不一致');
if(!/^U[0-9a-f]{32}$/.test(alerts[0].recipient))throw new Error('尚未設定本人LINE收件人');
const names={TSM:'台積電',NVDA:'輝達',GOOGL:'Google'};
const parts=alerts[0].date.split('-');const dateLabel=Number(parts[1])+'/'+Number(parts[2]);
const contents=[];
for(const r of alerts){
 if(contents.length)contents.push({type:'separator',color:'#E0E4E8',margin:'10px'});
 contents.push({type:'box',layout:'vertical',spacing:'4px',margin:contents.length?'10px':'none',contents:[
 {type:'text',text:(names[r.symbol]?names[r.symbol]+' · ':'')+r.symbol,weight:'bold',size:'15px',color:'#202A30',wrap:true,adjustMode:'shrink-to-fit'},
 {type:'text',text:'收盤價：$'+Number(r.close).toFixed(2)+' USD',size:'15px',color:'#202A30',wrap:true,adjustMode:'shrink-to-fit'},
 {type:'text',text:'單日漲跌：'+(r.changePct<0?'↓ ':r.changePct>0?'↑ ':'→ ')+Math.abs(r.changePct).toFixed(2)+'%',size:'15px',color:'#202A30',wrap:true,adjustMode:'shrink-to-fit'}]});
}
const title=dateLabel+' 美股收盤跌幅提醒通知';
const message={type:'flex',altText:title+'｜'+alerts.map(r=>r.symbol).join('、'),contents:{type:'bubble',size:'mega',
header:{type:'box',layout:'vertical',backgroundColor:'#193747',paddingAll:'14px',contents:[{type:'text',text:title,color:'#FFFFFF',weight:'bold',size:'16px',wrap:true,adjustMode:'shrink-to-fit'}]},
body:{type:'box',layout:'vertical',backgroundColor:'#FFFFFF',paddingAll:'14px',contents},
footer:{type:'box',layout:'vertical',backgroundColor:'#F0F2F5',paddingAll:'12px',contents:[{type:'text',text:'符合跌幅 '+alerts[0].thresholdPct+'% 門檻：'+alerts.length+' 檔',size:'15px',color:'#202A30',wrap:true,adjustMode:'shrink-to-fit'}]}}};
return [{json:{keys:manual?[]:alerts.map(r=>r.symbol+':'+r.date),source:{url:'https://twelvedata.com/',checkedAt:alerts[0].checkedAt},body:{to:alerts[0].recipient,messages:[message]}}}];

const response=$input.first().json;
if(response.statusCode!==200)throw new Error('LINE API未確認成功，未記錄已通知。');
const sent=$getWorkflowStaticData('global');sent.sent??={};
for(const key of $('整理提醒並排除重複').first().json.keys)sent.sent[key]=$now.toISO();
return [{json:{acceptedByLine:true,checkedAt:$now.toISO()}}];
